import java.util.*;
import java.io.*;

public class Main {
    static final long INF = 100000000000000000L;
    static final int MAXN = 1001;
    static final int[] dir_x = {0, 0, -1, 1};
    static final int[] dir_y = {-1, 1, 0, 0};
    static List<Integer>[] adj = new ArrayList[MAXN * 100]; // Max nodes based on problem constraints
    static boolean[] visited = new boolean[MAXN * 100];
    static int[] match = new int[MAXN * 100];

    static boolean is_valid(int x, int y, String[] grid) {
        int n = grid.length;
        return x >= 0 && y >= 0 && x < n && y < n && grid[x].charAt(y) != 'Y' && grid[x].charAt(y) != 'Z';
    }

    static long[][] get_distances(int sx, int sy, String[] grid) {
        int n = grid.length;
        long[][] dist = new long[n][n];
        for (long[] row : dist) Arrays.fill(row, INF);
        dist[sx][sy] = 0;
        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{sx, sy});
        while (!q.isEmpty()) {
            int[] cell = q.pollFirst();
            int x = cell[0], y = cell[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dir_x[d], ny = y + dir_y[d];
                if (!is_valid(nx, ny, grid) || dist[nx][ny] != INF) continue;
                dist[nx][ny] = dist[x][y] + 1;
                q.offer(new int[]{nx, ny});
            }
        }
        return dist;
    }

    static void build_graph(int n, int t, String[] s1, String[] s2) {
        int rx = -1, ry = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (s1[i].charAt(j) == 'Z') {
                    rx = i;
                    ry = j;
                }
            }
        }

        long[][] reac_dist = get_distances(rx, ry, s1);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (!is_valid(i, j, s1)) continue;
                long[][] from_cell = get_distances(i, j, s1);
                for (int x = 0; x < n; x++) {
                    for (int y = 0; y < n; y++) {
                        if (!is_valid(x, y, s1) || from_cell[x][y] > t || from_cell[x][y] > reac_dist[x][y]) continue;
                        if (from_cell[x][y] == reac_dist[x][y]) {
                            boolean can_move = false;
                            for (int dir_idx = 0; dir_idx < 4; dir_idx++) {
                                int xto = x + dir_x[dir_idx];
                                int yto = y + dir_y[dir_idx];
                                if (!is_valid(xto, yto, s1) || from_cell[xto][yto] >= reac_dist[xto][yto]) continue;
                                can_move = true;
                            }
                            if (!can_move) continue;
                        }
                        int max1 = s1[i].charAt(j) - '0';
                        int max2 = s2[x].charAt(y) - '0';
                        for (int num1 = 1; num1 <= max1; num1++) {
                            for (int num2 = 1; num2 <= max2; num2++) {
                                int v1 = 10 * (j + i * 10) + num1;
                                int v2 = 10 * (y + 10 * x) + num2;
                                if (adj[v1] == null) adj[v1] = new ArrayList<>();
                                adj[v1].add(v2);
                            }
                        }
                    }
                }
            }
        }
    }

    static boolean dfs(int v) {
        if (visited[v]) return false;
        visited[v] = true;
        if (adj[v] != null) {
            for (int to : adj[v]) {
                if (match[to] == 0 || dfs(match[to])) {
                    match[to] = v;
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());
        String[] s1 = new String[n];
        String[] s2 = new String[n];
        for (int i = 0; i < n; i++) s1[i] = br.readLine();
        for (int i = 0; i < n; i++) s2[i] = br.readLine();

        build_graph(n, t, s1, s2);

        int total_nodes = 100 * 10; // Based on maximum grid size and number ranges
        int res = 0;
        for (int i = 0; i < total_nodes; i++) {
            Arrays.fill(visited, false);
            dfs(i);
        }
        for (int i = 0; i < total_nodes; i++) {
            if (match[i] != 0) res++;
        }
        System.out.println(res);
    }
}
